//! Generates the service crates of the Origin Cloud SDK from the API
//! definitions (origincloudhq/api):
//!
//! ```text
//! origincloud-sdk-generator <api-dir> <out-dir>
//! ```
//!
//! `<api-dir>` is a checkout of the API; its dependencies are downloaded
//! at the commits its `buf.lock` pins. The generated files are written to
//! `<out-dir>` at their paths in this repository: for each proto package,
//! one file with its messages (prost-build), their proto3 JSON mapping
//! (pbjson-build) and its clients (this generator), and per crate a
//! `generated/mod.rs` declaring a module per version.
//!
//! `origincloud.longrunning.{version}` goes to the core crate, as
//! `origincloud_core::longrunning::{version}`; every other
//! `origincloud.{service}.{version}` to the crate `origincloud-{service}`,
//! as `origincloud_{service}::{version}`. A service without a crate gets
//! one scaffolded (see `scaffold`), with a notice on standard error.
//!
//! The output depends on nothing but the API checkout, the pinned
//! dependencies and the versions `Cargo.lock` pins, so generating from an
//! unchanged API changes nothing.

mod clients;
mod deps;
mod docs;
mod names;
mod scaffold;
mod support;

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail, ensure};
use prost::Message as _;
use prost_reflect::DescriptorPool;
use prost_types::FileDescriptorSet;
use protox::file::{
    ChainFileResolver, File, FileResolver, GoogleFileResolver, IncludeFileResolver,
};

const HEADER: &str = "// Code generated by origincloud-sdk-generator. DO NOT EDIT.\n";

/// A proto package and where its code goes.
struct Target {
    package: String,
    /// The crate's directory in the repository.
    crate_dir: String,
    /// The directory under the crate's `src` holding the `generated`
    /// module, empty for `src` itself.
    parent: String,
    /// The version, which names the package's module: `v1beta1`.
    version: String,
    /// The core crate's path from the generated code.
    core: &'static str,
}

impl Target {
    fn generated_dir(&self) -> PathBuf {
        let mut dir = PathBuf::from(&self.crate_dir).join("src");
        if !self.parent.is_empty() {
            dir.push(&self.parent);
        }
        dir.join("generated")
    }
}

fn main() -> Result<()> {
    let args: Vec<PathBuf> = std::env::args_os().skip(1).map(PathBuf::from).collect();
    let [api, out] = args.as_slice() else {
        bail!("usage: origincloud-sdk-generator <api-dir> <out-dir>");
    };
    let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .context("the generator is in the repository")?;

    let dependencies = deps::fetch(api)?;
    let (pool, mut fds) = compile(api, dependencies)?;
    let packages: BTreeSet<String> = pool
        .files()
        .filter(|f| f.name().starts_with("origincloud/"))
        .map(|f| f.package_name().to_owned())
        .collect();
    let comments = docs::clean(&mut fds, &pool, &packages);
    let encoded = fds.encode_to_vec();

    let (targets, new_services) = plan(&packages, repository)?;
    let mut files: BTreeMap<PathBuf, String> = BTreeMap::new();
    for (path, content) in scaffold::crates(repository, &new_services)? {
        files.insert(path, content);
    }
    for service in &new_services {
        eprintln!(
            "notice: origincloud.{service} is a new service: its crate, crates/{service}, was scaffolded \
             and added to the workspace; review its Cargo.toml and src/lib.rs"
        );
    }
    for target in &targets {
        let code = generate_package(target, &pool, &fds, &encoded, &comments)
            .with_context(|| target.package.clone())?;
        files.insert(
            target
                .generated_dir()
                .join(format!("{}.rs", target.package)),
            code,
        );
    }
    let mut modules: BTreeMap<PathBuf, Vec<&Target>> = BTreeMap::new();
    for target in &targets {
        modules
            .entry(target.generated_dir())
            .or_default()
            .push(target);
    }
    for (dir, targets) in modules {
        files.insert(dir.join("mod.rs"), module_file(&targets));
    }

    for (path, content) in &files {
        let path = out.join(path);
        std::fs::create_dir_all(path.parent().context("a file has a directory")?)?;
        std::fs::write(&path, content).with_context(|| format!("writing {}", path.display()))?;
    }
    Ok(())
}

/// Compiles every file under the API's `origincloud/`, with source info
/// and the files they import.
fn compile(
    api: &Path,
    dependencies: BTreeMap<String, String>,
) -> Result<(DescriptorPool, FileDescriptorSet)> {
    let mut resolver = ChainFileResolver::new();
    resolver.add(IncludeFileResolver::new(api.to_owned()));
    resolver.add(MemoryResolver(dependencies));
    resolver.add(GoogleFileResolver::new());
    let mut compiler = protox::Compiler::with_file_resolver(resolver);
    compiler.include_imports(true).include_source_info(true);

    let mut names = Vec::new();
    collect_protos(api, &api.join("origincloud"), &mut names)?;
    names.sort();
    ensure!(
        !names.is_empty(),
        "no .proto files under {}",
        api.join("origincloud").display()
    );
    compiler
        .open_files(&names)
        .map_err(|e| anyhow::anyhow!("{e:?}"))?;
    Ok((compiler.descriptor_pool(), compiler.file_descriptor_set()))
}

fn collect_protos(root: &Path, dir: &Path, names: &mut Vec<String>) -> Result<()> {
    for entry in std::fs::read_dir(dir).with_context(|| format!("reading {}", dir.display()))? {
        let path = entry?.path();
        if path.is_dir() {
            collect_protos(root, &path, names)?;
        } else if path.extension().is_some_and(|e| e == "proto") {
            let relative = path.strip_prefix(root)?;
            let name: Vec<String> = relative
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect();
            names.push(name.join("/"));
        }
    }
    Ok(())
}

/// The downloaded dependencies, by import path.
struct MemoryResolver(BTreeMap<String, String>);

impl FileResolver for MemoryResolver {
    fn open_file(&self, name: &str) -> Result<File, protox::Error> {
        match self.0.get(name) {
            Some(source) => File::from_source(name, source),
            None => Err(protox::Error::file_not_found(name)),
        }
    }
}

/// Where each package's code goes, and the services whose crate doesn't
/// exist yet.
fn plan(packages: &BTreeSet<String>, repository: &Path) -> Result<(Vec<Target>, Vec<String>)> {
    let mut targets = Vec::new();
    let mut new_services = Vec::new();
    for package in packages {
        let parts: Vec<&str> = package.split('.').collect();
        let ["origincloud", service, version] = parts.as_slice() else {
            bail!("the package {package} isn't origincloud.{{service}}.{{version}}");
        };
        let target = if *service == "longrunning" {
            Target {
                package: package.clone(),
                crate_dir: "crates/core".to_owned(),
                parent: "longrunning".to_owned(),
                version: (*version).to_owned(),
                core: "crate",
            }
        } else {
            ensure!(
                !service.is_empty()
                    && service
                        .bytes()
                        .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit()),
                "the service {service:?} of {package} can't name a crate"
            );
            let crate_dir = format!("crates/{service}");
            if !repository.join(&crate_dir).join("Cargo.toml").exists()
                && !new_services.iter().any(|s| s == service)
            {
                new_services.push((*service).to_owned());
            }
            Target {
                package: package.clone(),
                crate_dir,
                parent: String::new(),
                version: (*version).to_owned(),
                core: "::origincloud_core",
            }
        };
        targets.push(target);
    }
    Ok((targets, new_services))
}

/// The messages, their JSON mapping and the clients of one package.
fn generate_package(
    target: &Target,
    pool: &DescriptorPool,
    fds: &FileDescriptorSet,
    encoded: &[u8],
    comments: &docs::Comments,
) -> Result<String> {
    let core = target.core;
    let package = &target.package;
    support::check_fields(pool, package)?;
    let sources: Vec<_> = fds
        .file
        .iter()
        .filter(|f| f.package() == package)
        .cloned()
        .collect();

    let mut config = prost_build::Config::new();
    config
        .compile_well_known_types()
        .btree_map(["."])
        .extern_path(".google.protobuf", format!("{core}::protobuf"));
    let mut json = pbjson_build::Builder::new();
    json.register_descriptors(encoded)?
        .btree_map(["."])
        .ignore_unknown_fields()
        .ignore_unknown_enum_variants()
        .extern_path(".google.protobuf", format!("{core}::protobuf"));
    if !package.starts_with("origincloud.longrunning.") {
        config.extern_path(".origincloud.longrunning", format!("{core}::longrunning"));
        json.extern_path(".origincloud.longrunning", format!("{core}::longrunning"));
    }
    let module = prost_build::Module::from_protobuf_package_name(package);
    // Every file goes in, for prost-build to know the messages the
    // package's refer to; only the package's own module is kept.
    let requests = fds
        .file
        .iter()
        .map(|f| {
            (
                prost_build::Module::from_protobuf_package_name(f.package()),
                f.clone(),
            )
        })
        .collect();
    let mut messages = config.generate(requests)?;
    let messages = messages.remove(&module).unwrap_or_default();
    let mut serde = Vec::new();
    for (_, written) in json.generate(&[format!(".{package}")], |_| Ok(Vec::new()))? {
        serde.extend(written);
    }
    let clients = clients::generate(&clients::Generation {
        pool,
        comments,
        package,
        core,
    })?;

    let code = format!("{messages}\n{}\n{clients}", String::from_utf8(serde)?);
    let file = syn::parse_file(&code).context("the generated code doesn't parse")?;
    let mut source_list = String::new();
    for f in &sources {
        source_list.push_str(&format!("// source: {}\n", f.name()));
    }
    Ok(format!(
        "{HEADER}{source_list}\n{}",
        prettyplease::unparse(&file)
    ))
}

/// The `generated/mod.rs` of a crate: a module per version.
fn module_file(targets: &[&Target]) -> String {
    let mut out = String::from(HEADER);
    for target in targets {
        let stability = if target.version.contains("alpha") || target.version.contains("beta") {
            "a preview version: it may change in incompatible ways"
        } else {
            "a stable version: it never changes in incompatible ways"
        };
        out.push_str(&format!(
            "\n/// The `{}` API, {stability}.\n#[allow(clippy::all)]\npub mod {} {{\n    include!(\"{}.rs\");\n}}\n",
            target.package, target.version, target.package
        ));
    }
    out
}
